"use strict";(self.webpackChunkwww=self.webpackChunkwww||[]).push([[17238],{30438:(e,t,h)=>{h.r(t),h.d(t,{assets:()=>i,contentTitle:()=>a,default:()=>u,frontMatter:()=>s,metadata:()=>r,toc:()=>l});var n=h(31085),o=h(71184);const s={sidebar_position:28,slug:"/bible/Deuteronomy/Deuteronomy_28",title:"Deuteronomy 28",hide_table_of_contents:!0},a="Deuteronomy",r={id:"bible/Deuteronomy/Deuteronomy 28",title:"Deuteronomy 28",description:"Chapter 28",source:"@site/docs/bible/Deuteronomy/Deuteronomy 28.md",sourceDirName:"bible/Deuteronomy",slug:"/bible/Deuteronomy/Deuteronomy_28",permalink:"/docs/bible/Deuteronomy/Deuteronomy_28",draft:!1,unlisted:!1,editUrl:"https://github.com/ozkey/bibleNotes/docs/bible/Deuteronomy/Deuteronomy 28.md",tags:[],version:"current",sidebarPosition:28,frontMatter:{sidebar_position:28,slug:"/bible/Deuteronomy/Deuteronomy_28",title:"Deuteronomy 28",hide_table_of_contents:!0},sidebar:"bibleSidebar",previous:{title:"Deuteronomy 27",permalink:"/docs/bible/Deuteronomy/Deuteronomy_27"},next:{title:"Deuteronomy 29",permalink:"/docs/bible/Deuteronomy/Deuteronomy_29"}},i={},l=[{value:"Chapter 28",id:"chapter-28",level:2}];function d(e){const t={admonition:"admonition",h1:"h1",h2:"h2",p:"p",...(0,o.R)(),...e.components},{BibleText:h}=t;return h||function(e,t){throw new Error("Expected "+(t?"component":"object")+" `"+e+"` to be defined: you likely forgot to import, pass, or provide it.")}("BibleText",!0),(0,n.jsxs)(n.Fragment,{children:[(0,n.jsx)(t.h1,{id:"deuteronomy",children:"Deuteronomy"}),"\n",(0,n.jsx)(t.h2,{id:"chapter-28",children:"Chapter 28"}),"\n",(0,n.jsx)(t.p,{children:"Many blessings are promised to observers of God's commandments:  and curses threatened to transgressors."}),"\n",(0,n.jsx)(h,{verse:1,children:"Now if thou wilt hear the voice of all his commandments, which I command thee this day, the Lord thy God will make thee higher than all the nations that are on the earth."}),"\n",(0,n.jsx)(h,{verse:2,children:"And all these blessings shall come upon thee and overtake thee: yet so if thou hear his precepts."}),"\n",(0,n.jsx)(t.admonition,{type:"note",children:(0,n.jsx)(t.p,{children:"Note 1: All these blessings, etc...In the Old Testament, God promised temporal blessings to the keepers of his law, heaven not being opened as yet; and that gross and sensual people being more moved with present and sensible things. But in the New Testament the goods that are promised us are spiritual and eternal; and temporal evils are turned into blessings."})}),"\n",(0,n.jsx)(h,{verse:3,children:"Blessed shalt thou be in the city, and blessed in the field."}),"\n",(0,n.jsx)(h,{verse:4,children:"Blessed shall be the fruit of thy womb, and the fruit of thy ground, and the fruit of thy cattle, the droves of thy herds, and the folds of thy sheep."}),"\n",(0,n.jsx)(h,{verse:5,children:"Blessed shall be thy barns and blessed thy stores."}),"\n",(0,n.jsx)(h,{verse:6,children:"Blessed shalt thou be coming in and going out."}),"\n",(0,n.jsx)(h,{verse:7,children:"The Lord shall cause thy enemies, that rise up against thee, to fall down before thy face: one way shall they come out against thee, and seven ways shall they flee before thee."}),"\n",(0,n.jsx)(h,{verse:8,children:"The Lord will send forth a blessing upon thy storehouses, and upon all the works of thy hands: and will bless thee in the land that thou shalt receive."}),"\n",(0,n.jsx)(h,{verse:9,children:"The Lord will raise thee up to be a holy people to himself, as he swore to thee: if thou keep the commandments of the Lord thy God, and walk in his ways."}),"\n",(0,n.jsx)(h,{verse:10,children:"And all the people of the earth shall see that the name of the Lord is invocated upon thee, and they shall fear thee."}),"\n",(0,n.jsx)(h,{verse:11,children:"The Lord will make thee abound with all goods, with the fruit of thy womb, and the fruit of thy cattle, with the fruit of thy land, which the Lord swore to thy fathers that he would give thee."}),"\n",(0,n.jsx)(h,{verse:12,children:"The Lord will open his excellent treasure, the heaven, that it may give rain in due season: and he will bless all the works of thy hands. And thou shalt lend to many nations, and shalt not borrow of any one."}),"\n",(0,n.jsx)(h,{verse:13,children:"And the Lord shall make thee the head and not the tail: and thou shalt be always above, and not beneath: yet so if thou wilt hear the commandments of the Lord thy God which I command thee this day, and keep and do them,"}),"\n",(0,n.jsx)(h,{verse:14,children:"And turn not away from them neither to the right hand, nor to the left, nor follow strange gods, nor worship them."}),"\n",(0,n.jsx)(h,{verse:15,children:"But if thou wilt not hear the voice of the Lord thy God, to keep and to do all his commandments and ceremonies, which I command thee this day, all these curses shall come upon thee, and overtake thee."}),"\n",(0,n.jsx)(t.admonition,{type:"note",children:(0,n.jsx)(t.p,{children:"Note 1: All these curses, etc...Thus God dealt with the transgressors of his law in the Old Testament: but now he often suffers sinners to prosper in this world, rewarding them for some little good they have done, and reserving their punishment for the other world."})}),"\n",(0,n.jsx)(h,{verse:16,children:"Cursed shalt thou be in the city, cursed in the field."}),"\n",(0,n.jsx)(h,{verse:17,children:"Cursed shall be thy barn, and cursed thy stores."}),"\n",(0,n.jsx)(h,{verse:18,children:"Cursed shall be the fruit of thy womb, and the fruit of thy ground, the herds of thy oxen, and the flocks of thy sheep."}),"\n",(0,n.jsx)(h,{verse:19,children:"Cursed shalt thou be coming in, and cursed going out."}),"\n",(0,n.jsx)(h,{verse:20,children:"The Lord shall send upon thee famine and hunger, and a rebuke upon all the works which thou shalt do: until he consume and destroy thee quickly, for thy most wicked inventions, by which thou hast forsaken me."}),"\n",(0,n.jsx)(h,{verse:21,children:"May the Lord set the pestilence upon thee, until he consume thee out of the land, which thou shalt go in to possess."}),"\n",(0,n.jsx)(h,{verse:22,children:"May the Lord afflict thee with miserable want, with the fever and with cold, with burning and with heat, and with corrupted air and with blasting, and pursue thee till thou perish."}),"\n",(0,n.jsx)(h,{verse:23,children:"Be the heaven, that is over thee, of brass: and the ground thou treadest on, of iron."}),"\n",(0,n.jsx)(h,{verse:24,children:"The Lord give thee dust for rain upon thy land, and let ashes come down from heaven upon thee, till thou be consumed."}),"\n",(0,n.jsx)(h,{verse:25,children:"The Lord make thee to fall down before thy enemies, one way mayst thou go out against them, and flee seven ways, and be scattered throughout all the kingdoms of the earth."}),"\n",(0,n.jsx)(h,{verse:26,children:"And be thy carcass meat for all the fowls of the air, and the beasts of the earth, and be there none to drive them away."}),"\n",(0,n.jsx)(h,{verse:27,children:"The Lord strike thee with the ulcer of Egypt, and the part of thy body, by which the dung is cast out, with the scab and with the itch: so that thou canst not be healed."}),"\n",(0,n.jsx)(h,{verse:28,children:"The Lord strike thee with madness and blindness and fury of mind."}),"\n",(0,n.jsx)(h,{verse:29,children:"And mayst thou grope at midday as the blind is wont to grope in the dark, and not make straight thy ways. And mayst thou at all times suffer wrong, and be oppressed with violence, and mayst thou have no one to deliver thee."}),"\n",(0,n.jsx)(h,{verse:30,children:"Mayst thou take a wife, and another sleep with her. Mayst thou build a house, and not dwell therein. Mayest thou plant a vineyard and not gather the vintage thereof."}),"\n",(0,n.jsx)(h,{verse:31,children:"May thy ox be slain before thee, and thou not eat thereof. May thy ass be taken away in thy sight, and not restored to thee. May thy sheep be given to thy enemies, and may there be none to help thee."}),"\n",(0,n.jsx)(h,{verse:32,children:"May thy sons and thy daughters be given to another people, thy eyes looking on, and languishing at the sight of them all the day, and may there be no strength in thy hand."}),"\n",(0,n.jsx)(h,{verse:33,children:"May a people which thou knowest not, eat the fruits of thy land, and all thy labours: and mayst thou always suffer oppression, and be crushed at all times."}),"\n",(0,n.jsx)(h,{verse:34,children:"And be astonished at the terror of those things which thy eyes shall see:"}),"\n",(0,n.jsx)(h,{verse:35,children:"May the Lord strike thee with a very sore ulcer in the knees and in the legs, and be thou incurable from the sole of the foot to the top of the head."}),"\n",(0,n.jsx)(h,{verse:36,children:"The Lord shall bring thee, and thy king, whom thou shalt have appointed over thee, into a nation which thou and thy fathers know not: and there thou shalt serve strange gods, wood and stone."}),"\n",(0,n.jsx)(h,{verse:37,children:"And thou shalt be lost, as a proverb and a byword to all people, among whom the Lord shall bring thee in."}),"\n",(0,n.jsx)(h,{verse:38,children:"Thou shalt cast much seed into the ground, and gather little: because the locusts shall consume all."}),"\n",(0,n.jsx)(h,{verse:39,children:"Thou shalt plant a vineyard, and dig it, and shalt not drink the wine, nor gather any thing thereof: because it shall be wasted with worms."}),"\n",(0,n.jsx)(h,{verse:40,children:"Thou shalt have olive trees in all thy borders, and shalt not be anointed with the oil: for the olives shall fall off and perish."}),"\n",(0,n.jsx)(h,{verse:41,children:"Thou shalt beget sons and daughters, and shalt not enjoy them: because they shall be led into captivity."}),"\n",(0,n.jsx)(h,{verse:42,children:"The blast shall consume all the trees and the fruits of thy ground."}),"\n",(0,n.jsx)(h,{verse:43,children:"The stranger that liveth with thee in the land, shall rise up over thee, and shall be higher: and thou shalt go down, and be lower."}),"\n",(0,n.jsx)(h,{verse:44,children:"He shall lend to thee, and thou shalt not lend to him. He shall be as the head, and thou shalt be the tail."}),"\n",(0,n.jsx)(h,{verse:45,children:"And all these curses shall come upon thee, and shall pursue and overtake thee, till thou perish: because thou heardst not the voice of the Lord thy God, and didst not keep his commandments and ceremonies which he commanded thee."}),"\n",(0,n.jsx)(h,{verse:46,children:"And they shall be as signs and wonders on thee, and on thy seed for ever."}),"\n",(0,n.jsx)(h,{verse:47,children:"Because thou didst not serve the Lord thy God with joy and gladness of heart, for the abundance of all things:"}),"\n",(0,n.jsx)(h,{verse:48,children:"Thou shalt serve thy enemy, whom the Lord will send upon thee, in hunger, and thirst, and nakedness, and in want of all things: and he shall put an iron yoke upon thy neck, till he consume thee."}),"\n",(0,n.jsx)(h,{verse:49,children:"The Lord will bring upon thee a nation from afar, and from the uttermost ends of the earth, like an eagle that flyeth swiftly, whose tongue thou canst not understand,"}),"\n",(0,n.jsx)(h,{verse:50,children:"A most insolent nation, that will shew no regard to the ancients, nor have pity on the infant,"}),"\n",(0,n.jsx)(h,{verse:51,children:"And will devour the fruit of thy cattle, and the fruits of thy land: until thou be destroyed, and will leave thee no wheat, nor wine, nor oil, nor herds of oxen, nor flocks of sheep: until he destroy thee."}),"\n",(0,n.jsx)(h,{verse:52,children:"And consume thee in all thy cities, and thy strong and high wall be brought down, wherein thou trustedst in all thy land. Thou shalt be besieged within thy gates in all thy land which the Lord thy God will give thee:"}),"\n",(0,n.jsx)(h,{verse:53,children:"And thou shalt eat the fruit of thy womb, and the flesh of thy sons and of thy daughters, which the Lord thy God shall give thee, in the distress and extremity wherewith thy enemy shall oppress thee."}),"\n",(0,n.jsx)(h,{verse:54,children:"The man that is nice among you, and very delicate, shall envy his own brother, and his wife, that lieth in his bosom,"}),"\n",(0,n.jsx)(h,{verse:55,children:"So that he will not give them of the flesh of his children, which he shall eat: because he hath nothing else in the siege and the want, wherewith thy enemies shall distress thee within all thy gates."}),"\n",(0,n.jsx)(h,{verse:56,children:"The tender and delicate woman, that could not go upon the ground, nor set down her foot for over much niceness and tenderness, will envy her husband who lieth in her bosom, the flesh of her son, and of her daughter,"}),"\n",(0,n.jsx)(h,{verse:57,children:"And the filth of the afterbirths, that come forth from between her thighs, and the children that are born the same hour. For they shall eat them secretly for the want of all things, in the siege and distress, wherewith thy enemy shall oppress thee within thy gates."}),"\n",(0,n.jsx)(h,{verse:58,children:"If thou wilt not keep, and fulfil all the words of this law, that are written in this volume, and fear his glorious and terrible name: that is, The Lord thy God:"}),"\n",(0,n.jsx)(h,{verse:59,children:"The Lord shall increase thy plagues, and the plagues of thy seed, plagues great and lasting, infirmities grievous and perpetual."}),"\n",(0,n.jsx)(h,{verse:60,children:"And he shall bring back on thee all the afflictions of Egypt, which thou wast afraid of, and they shall stick fast to thee."}),"\n",(0,n.jsx)(h,{verse:61,children:"Moreover the Lord will bring upon thee all the diseases, and plagues, that are not written in the volume of this law till he consume thee:"}),"\n",(0,n.jsx)(h,{verse:62,children:"And you shall remain few in number, who before were as the stars of heaven for multitude, because thou heardst not the voice of the Lord thy God."}),"\n",(0,n.jsx)(h,{verse:63,children:"And as the Lord rejoiced upon you before doing good to you, and multiplying you: so he shall rejoice destroying and bringing you to nought, so that you shall be taken away from the land which thou shalt go in to possess."}),"\n",(0,n.jsx)(h,{verse:64,children:"The Lord shall scatter thee among all people, from the farthest parts of the earth to the ends thereof: and there thou shalt serve strange gods, which both thou art ignorant of and thy fathers, wood and stone."}),"\n",(0,n.jsx)(h,{verse:65,children:"Neither shalt thou be quiet, even in those nations, nor shall there be any rest for the sole of thy foot. For the Lord will give thee a fearful heart, and languishing eyes, and a soul consumed with pensiveness:"}),"\n",(0,n.jsx)(h,{verse:66,children:"And thy life shall be as it were hanging before thee. Thou shalt fear night and day, neither shalt thou trust thy life."}),"\n",(0,n.jsx)(h,{verse:67,children:"In the morning thou shalt say: Who will grant me evening? and at evening: Who will grant me morning? for the fearfulness of thy heart, wherewith thou shalt be terrified, and for those things which thou shalt see with thy eyes."}),"\n",(0,n.jsx)(h,{verse:68,children:"The Lord shall bring thee again with ships into Egypt, by the way whereof he said to thee that thou shouldst see it no more. There shalt thou be set to sale to thy enemies for bondmen and bondwomen, and no man shall buy you."})]})}function u(e={}){const{wrapper:t}={...(0,o.R)(),...e.components};return t?(0,n.jsx)(t,{...e,children:(0,n.jsx)(d,{...e})}):d(e)}},71184:(e,t,h)=>{h.d(t,{R:()=>a,x:()=>r});var n=h(14041);const o={},s=n.createContext(o);function a(e){const t=n.useContext(s);return n.useMemo((function(){return"function"==typeof e?e(t):{...t,...e}}),[t,e])}function r(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(o):e.components||o:a(e.components),n.createElement(s.Provider,{value:t},e.children)}}}]);